SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, (COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) - COUNT(CASE WHEN p.dod IS NULL THEN 1 END)) / NULLIF(COUNT(p.subject_id), 0) AS mortality_difference, COUNT(CASE WHEN v.itemid IN (151001, 151002, 151003) THEN 1 END) / NULLIF(COUNT(p.subject_id), 0) AS vent_prevalence, COUNT(CASE WHEN d.icd_code IN (100, 101, 102) THEN 1 END) / NULLIF(COUNT(p.subject_id), 0) AS diabetes_prevalence, COUNT(CASE WHEN c.score BETWEEN 0 AND 1 THEN 1 END) / NULLIF(COUNT(p.subject_id), 0) AS charlson_0_1_prevalence, COUNT(CASE WHEN c.score BETWEEN 2 AND 3 THEN 1 END) / NULLIF(COUNT(p.subject_id), 0) AS charlson_2_3_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN chartevents c ON a.subject_id = c.subject_id AND a.hadm_id = c.hadm_id JOIN datetimesevents d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id AND a.stay_id = d.stay_id JOIN inputevents v ON a.subject_id = v.subject_id AND a.hadm_id = v.hadm_id AND a.stay_id = v.stay_id WHERE p.gender = 'M' AND p.anchor_age = 49 AND p.hadm_id IN (SELECT hadm_id FROM icustays WHERE length_of_stay <= 7) AND (c.score BETWEEN 0 AND 1 OR c.score BETWEEN 2 AND 3) GROUP BY p.subject_id HAVING COUNT(CASE WHEN v.itemid IN (151001, 151002, 151003) THEN 1 END) > 0;